import{_ as n,o as r,c as s,ai as t}from"./chunks/framework.Ai2o9gNv.js";const e="/assets/image-20260630230139157.B6Qzs4jv.png",a="/assets/image-20260630230158050.DLDfWs5A.png",i="/assets/image-20260630230224224.BKpb0Ezb.png",g="/assets/image-20260630230413613.jBKBguhK.png",p="/assets/image-20260630231042313.cMxn9vkI.png",l="/assets/image-20260630231944391.BSXSVAwd.png",d="/assets/image-20260630232537321.2ejl6BtN.png",k="/assets/image-20260630232548137.XI_kPidZ.png",_="/assets/image-20260630233048366.BWExo_uA.png",m="/assets/image-20260630233434085.C59UUToN.png",c="/assets/image-20260630233743558.GFelQD4u.png",f=JSON.parse('{"title":"22 点后，我靠这个 AI 工具成了\\"夜间天才程序员\\"","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/22 点后，我靠这个 AI 工具成了夜间天才程序员/22 点后，我靠这个 AI 工具成了夜间天才程序员.md","filePath":"AI人工智能/22 点后，我靠这个 AI 工具成了夜间天才程序员/22 点后，我靠这个 AI 工具成了夜间天才程序员.md","lastUpdated":1782838421000,"__rawMarkdown":"# 22 点后，我靠这个 AI 工具成了\\"夜间天才程序员\\"\\n\\n## 前言\\n\\n大家好，我是**万少**，一个深耕鸿蒙和 AI 的技术人员。\\n\\n最近深度沉浸在 AI 造物中无法自拔，**同时运作多个项目**已经是常态。今天来聊聊阿里的一款产品——**QoderWork**。\\n\\n## 阿里的 Qoder 家族\\n\\n> 官网：https://qoder.com/zh?spm=5176.28644950.0.0.77f93ea8i0ei9c\\n\\n阿里最近推出了多款面向用户的 AI 产品，简单梳理一下：\\n\\n- **面向程序员**：Qoder Desktop、QoderCli\\n- **面向日常办公（也包含编程）**：QoderWork\\n- **面向老板（偏向全领域）**：QoderWake\\n\\n我们分别看看它们的介绍。\\n\\n**Qoder Desktop 和 QoderCli**\\n\\n![](assets/image-20260630230139157.png)\\n\\n---\\n\\n![](assets/image-20260630230158050.png)\\n\\n**QoderWork**\\n\\n![](assets/image-20260630230224224.png)\\n\\n---\\n\\n**QoderWake**\\n\\n![](assets/image-20260630230413613.png)\\n\\n---\\n\\n作为牛马，QoderWake 的标语——**「各司其职，全天在线的数字员工」**——实在扎心。\\n\\n## 为什么主要聊 QoderWork\\n\\n万少个人的感觉是：**QoderWork 的功能其实最全面。**\\n\\n1. **该有的功能，全都有**\\n\\n2. **可视化界面，操作友好**：哪怕你是编程人士，也可以通过对话窗口轻松管理多个项目。只需要打开一个 QoderWork，就能管理其他路径下的所有任务，不管是编程还是日常办公。\\n\\n3. **新特性上得最快**：截至 2026 年 6 月 30 日，万少找了一圈国内的各种 AI 工具，目前都没有上线 Windows 系统下的 **Computer Use** 能力，**只有 QoderWork 已经有了**。虽然是 beta 版本，但这一点直接命中我的硬需求——我需要的是一个能真正自动操作电脑的 AI 工具，而不是普通的\\"聊天类\\"产品，它能**直接帮你点击屏幕、模拟鼠标操作**。\\n\\n4. **夜间模型，token 费用打折**：22:00 - 08:00 这个时间段，Qwen 顶尖模型的费用如下图。\\n\\n   ![](assets/image-20260630231042313.png)\\n\\n   ---\\n\\n   需要注意的是：**Qwen3.7-Max** 能力最强，但不是多模态；**Qwen3.7-Plus** 略次之，却是多模态，而且费用最低。万少夜间办公用的就是 **Qwen3.7-Plus**。\\n\\n## QoderWork 基本使用介绍\\n\\nQoderWork 提供的功能有：**新任务、专家套件、技能、连接器、定时任务**和 **IM 频道**。\\n\\n### 新任务\\n\\n其实就是对话框，表示你当前要做什么任务。如果只是简单的问答，直接用就行；如果需要编辑本地文件（比如编程、改 Word 文档等），建议**先选择工作空间**，这样方便对本地文件做修改。\\n\\n![](assets/image-20260630231944391.png)\\n\\n### 技能\\n\\n技能就是 **skill**，前段时间刷爆全网的就是它。可以理解为：**一个 skill 就是一段任务的详细描述**——你可以自己创建，也可以复用别人做好的。\\n\\nQoderWork 中的技能是官方认可的一些可复用技能，目前有三种类型：\\n\\n![](assets/image-20260630232537321.png)\\n\\n1. **内置**：QoderWork 中已经集成的，可以直接使用。\\n2. **市场**：QoderWork 提供的一个平台，方便大家上传、分享和下载优秀技能。\\n3. **已安装**：你已经在本地装好的技能。\\n\\n当然，所谓的技能和 skill，在物理形态上也就是**一堆文件 + 一点描述**。既然是文件，那就是可迁移的——也就是说，各个 AI 产品的技能都可以互相导入使用。所以 QoderWork 也提供了**导入本地其他 AI 产品 skill** 的能力。\\n\\n![](assets/image-20260630232548137.png)\\n\\n像万少的主力工具 **Claude Code**，其实已经沉淀了不少 skill，一样可以直接导入给 QoderWork 使用。\\n\\n![](assets/image-20260630233048366.png)\\n\\n> 这些新工具的玩法和踩坑经验，万少平时都会第一时间在一个 AI 交流群里分享——**文末有进群方式**。\\n\\n### 连接器\\n\\n连接器，是你的 QoderWork 用来**连接其他网站、其他软件**的桥梁。\\n\\n比如，你可以用 QoderWork 控制钉钉发一篇文档，也可以让它控制飞书统计一张报表。这样就实现了**跨软件之间的联动**——结合实际需求，需要什么就加什么。\\n\\n![](assets/image-20260630233434085.png)\\n\\n---\\n\\n其中，**眼尖**的小伙伴应该已经注意到了：有一个叫 **「计算机控制」** 的连接器。没错，这就是我使用 QoderWork 最大的原因——目前只有它提供了控制电脑的功能，可以帮我做不少自动化工作。\\n\\n### 专家套件\\n\\n专家套件，可以理解为是上面所有功能的**集合**。举个拍电影的例子（万少非专业）：\\n\\n1. 需要挑选演员\\n2. 需要编写剧本\\n3. 需要剪辑视频\\n4. 需要制定营销方案\\n\\n---\\n\\n上面的需求综合起来，其实就是**一堆能力围绕同一个目的、同一个领域的堆叠**。所以这里就引入了\\"专家套件\\"这个能力。\\n\\n![](assets/image-20260630233743558.png)\\n\\n---\\n\\n比如买家助手、企业法务、市场营销、咨询交付等等，很多企业需要的垂直领域专家都已经提供，**开箱即用**。\\n\\n## 写在最后\\n\\nAI 时代正在带来各行各业的变革，**多了解一些，总归是有好处的**。\\n\\n毕竟，未来的程序员，可能不是写代码最快的那个，而是**最会用 AI 的那个**。\\n\\n> 如果你也想找个地方聊聊 AI、互通新工具有无，欢迎进我的 **AI 交流群**。\\n>\\n> 👇 关注公众号「**你的公众号名字**」，回复关键词 **【AI工具】**，我拉你进群。\\n"}'),h={name:"AI人工智能/22 点后，我靠这个 AI 工具成了夜间天才程序员/22 点后，我靠这个 AI 工具成了夜间天才程序员.md"};function Q(u,o,W,A,I,q){return r(),s("div",null,[...o[0]||(o[0]=[t('<h1 id="_22-点后-我靠这个-ai-工具成了-夜间天才程序员" tabindex="-1">22 点后，我靠这个 AI 工具成了&quot;夜间天才程序员&quot; <a class="header-anchor" href="#_22-点后-我靠这个-ai-工具成了-夜间天才程序员" aria-label="Permalink to &quot;22 点后，我靠这个 AI 工具成了&quot;夜间天才程序员&quot;&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>大家好，我是<strong>万少</strong>，一个深耕鸿蒙和 AI 的技术人员。</p><p>最近深度沉浸在 AI 造物中无法自拔，<strong>同时运作多个项目</strong>已经是常态。今天来聊聊阿里的一款产品——<strong>QoderWork</strong>。</p><h2 id="阿里的-qoder-家族" tabindex="-1">阿里的 Qoder 家族 <a class="header-anchor" href="#阿里的-qoder-家族" aria-label="Permalink to &quot;阿里的 Qoder 家族&quot;">​</a></h2><blockquote><p>官网：<a href="https://qoder.com/zh?spm=5176.28644950.0.0.77f93ea8i0ei9c" target="_blank" rel="noreferrer">https://qoder.com/zh?spm=5176.28644950.0.0.77f93ea8i0ei9c</a></p></blockquote><p>阿里最近推出了多款面向用户的 AI 产品，简单梳理一下：</p><ul><li><strong>面向程序员</strong>：Qoder Desktop、QoderCli</li><li><strong>面向日常办公（也包含编程）</strong>：QoderWork</li><li><strong>面向老板（偏向全领域）</strong>：QoderWake</li></ul><p>我们分别看看它们的介绍。</p><p><strong>Qoder Desktop 和 QoderCli</strong></p><p><img src="'+e+'" alt=""></p><hr><p><img src="'+a+'" alt=""></p><p><strong>QoderWork</strong></p><p><img src="'+i+'" alt=""></p><hr><p><strong>QoderWake</strong></p><p><img src="'+g+'" alt=""></p><hr><p>作为牛马，QoderWake 的标语——<strong>「各司其职，全天在线的数字员工」</strong>——实在扎心。</p><h2 id="为什么主要聊-qoderwork" tabindex="-1">为什么主要聊 QoderWork <a class="header-anchor" href="#为什么主要聊-qoderwork" aria-label="Permalink to &quot;为什么主要聊 QoderWork&quot;">​</a></h2><p>万少个人的感觉是：<strong>QoderWork 的功能其实最全面。</strong></p><ol><li><p><strong>该有的功能，全都有</strong></p></li><li><p><strong>可视化界面，操作友好</strong>：哪怕你是编程人士，也可以通过对话窗口轻松管理多个项目。只需要打开一个 QoderWork，就能管理其他路径下的所有任务，不管是编程还是日常办公。</p></li><li><p><strong>新特性上得最快</strong>：截至 2026 年 6 月 30 日，万少找了一圈国内的各种 AI 工具，目前都没有上线 Windows 系统下的 <strong>Computer Use</strong> 能力，<strong>只有 QoderWork 已经有了</strong>。虽然是 beta 版本，但这一点直接命中我的硬需求——我需要的是一个能真正自动操作电脑的 AI 工具，而不是普通的&quot;聊天类&quot;产品，它能<strong>直接帮你点击屏幕、模拟鼠标操作</strong>。</p></li><li><p><strong>夜间模型，token 费用打折</strong>：22:00 - 08:00 这个时间段，Qwen 顶尖模型的费用如下图。</p><p><img src="'+p+'" alt=""></p><hr><p>需要注意的是：<strong>Qwen3.7-Max</strong> 能力最强，但不是多模态；<strong>Qwen3.7-Plus</strong> 略次之，却是多模态，而且费用最低。万少夜间办公用的就是 <strong>Qwen3.7-Plus</strong>。</p></li></ol><h2 id="qoderwork-基本使用介绍" tabindex="-1">QoderWork 基本使用介绍 <a class="header-anchor" href="#qoderwork-基本使用介绍" aria-label="Permalink to &quot;QoderWork 基本使用介绍&quot;">​</a></h2><p>QoderWork 提供的功能有：<strong>新任务、专家套件、技能、连接器、定时任务</strong>和 <strong>IM 频道</strong>。</p><h3 id="新任务" tabindex="-1">新任务 <a class="header-anchor" href="#新任务" aria-label="Permalink to &quot;新任务&quot;">​</a></h3><p>其实就是对话框，表示你当前要做什么任务。如果只是简单的问答，直接用就行；如果需要编辑本地文件（比如编程、改 Word 文档等），建议<strong>先选择工作空间</strong>，这样方便对本地文件做修改。</p><p><img src="'+l+'" alt=""></p><h3 id="技能" tabindex="-1">技能 <a class="header-anchor" href="#技能" aria-label="Permalink to &quot;技能&quot;">​</a></h3><p>技能就是 <strong>skill</strong>，前段时间刷爆全网的就是它。可以理解为：<strong>一个 skill 就是一段任务的详细描述</strong>——你可以自己创建，也可以复用别人做好的。</p><p>QoderWork 中的技能是官方认可的一些可复用技能，目前有三种类型：</p><p><img src="'+d+'" alt=""></p><ol><li><strong>内置</strong>：QoderWork 中已经集成的，可以直接使用。</li><li><strong>市场</strong>：QoderWork 提供的一个平台，方便大家上传、分享和下载优秀技能。</li><li><strong>已安装</strong>：你已经在本地装好的技能。</li></ol><p>当然，所谓的技能和 skill，在物理形态上也就是<strong>一堆文件 + 一点描述</strong>。既然是文件，那就是可迁移的——也就是说，各个 AI 产品的技能都可以互相导入使用。所以 QoderWork 也提供了<strong>导入本地其他 AI 产品 skill</strong> 的能力。</p><p><img src="'+k+'" alt=""></p><p>像万少的主力工具 <strong>Claude Code</strong>，其实已经沉淀了不少 skill，一样可以直接导入给 QoderWork 使用。</p><p><img src="'+_+'" alt=""></p><blockquote><p>这些新工具的玩法和踩坑经验，万少平时都会第一时间在一个 AI 交流群里分享——<strong>文末有进群方式</strong>。</p></blockquote><h3 id="连接器" tabindex="-1">连接器 <a class="header-anchor" href="#连接器" aria-label="Permalink to &quot;连接器&quot;">​</a></h3><p>连接器，是你的 QoderWork 用来<strong>连接其他网站、其他软件</strong>的桥梁。</p><p>比如，你可以用 QoderWork 控制钉钉发一篇文档，也可以让它控制飞书统计一张报表。这样就实现了<strong>跨软件之间的联动</strong>——结合实际需求，需要什么就加什么。</p><p><img src="'+m+'" alt=""></p><hr><p>其中，<strong>眼尖</strong>的小伙伴应该已经注意到了：有一个叫 <strong>「计算机控制」</strong> 的连接器。没错，这就是我使用 QoderWork 最大的原因——目前只有它提供了控制电脑的功能，可以帮我做不少自动化工作。</p><h3 id="专家套件" tabindex="-1">专家套件 <a class="header-anchor" href="#专家套件" aria-label="Permalink to &quot;专家套件&quot;">​</a></h3><p>专家套件，可以理解为是上面所有功能的<strong>集合</strong>。举个拍电影的例子（万少非专业）：</p><ol><li>需要挑选演员</li><li>需要编写剧本</li><li>需要剪辑视频</li><li>需要制定营销方案</li></ol><hr><p>上面的需求综合起来，其实就是<strong>一堆能力围绕同一个目的、同一个领域的堆叠</strong>。所以这里就引入了&quot;专家套件&quot;这个能力。</p><p><img src="'+c+'" alt=""></p><hr><p>比如买家助手、企业法务、市场营销、咨询交付等等，很多企业需要的垂直领域专家都已经提供，<strong>开箱即用</strong>。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>AI 时代正在带来各行各业的变革，<strong>多了解一些，总归是有好处的</strong>。</p><p>毕竟，未来的程序员，可能不是写代码最快的那个，而是<strong>最会用 AI 的那个</strong>。</p><blockquote><p>如果你也想找个地方聊聊 AI、互通新工具有无，欢迎进我的 <strong>AI 交流群</strong>。</p><p>👇 关注公众号「<strong>你的公众号名字</strong>」，回复关键词 <strong>【AI工具】</strong>，我拉你进群。</p></blockquote>',56)])])}const P=n(h,[["render",Q]]);export{f as __pageData,P as default};
